"""Keep the paper as ONE LaTeX document (paper/main.tex) while tables and number macros are still generated by scripts.

  python scripts/tex_single.py flatten   one-off: inline numbers.tex, sections/*.tex and tables/*.tex into main.tex,
                                         wrapping every generated block in markers (% >>> name ... % <<< name);
                                         the section files are moved to paper/_old_sections/
  python scripts/tex_single.py sync      after make_numbers.py / make_tables.py: replace the marked blocks in main.tex
                                         with the regenerated numbers.tex and tables/*.tex (hand edits elsewhere survive)
"""
from __future__ import annotations

import re
import shutil
import sys
from pathlib import Path

P = Path("paper")
BEGIN, END = "% >>> {name} (generated: do not edit, run scripts/tex_single.py sync)", "% <<< {name}"


def block(name: str, body: str) -> str:
    return BEGIN.format(name=name) + "\n" + body.rstrip("\n") + "\n" + END.format(name=name)


def inline_tables(text: str) -> str:
    def repl(m):
        name = m.group(1)
        return block(name, (P / "tables" / f"{name}.tex").read_text(encoding="utf-8"))
    return re.sub(r"^\\input\{tables/(tab_[a-z_]+)\}\s*$", repl, text, flags=re.M)


def flatten():
    main = (P / "main.tex").read_text(encoding="utf-8")
    assert "\\input{sections/" in main, "main.tex is already flat"
    main = main.replace("\\input{numbers.tex}", block("numbers", (P / "numbers.tex").read_text(encoding="utf-8")))

    def repl(m):
        return inline_tables((P / "sections" / f"{m.group(1)}.tex").read_text(encoding="utf-8")).rstrip("\n")
    main = re.sub(r"^\\input\{sections/([a-z]+)\}\s*$", repl, main, flags=re.M)
    assert "\\input{sections/" not in main and "\\input{tables/" not in main
    shutil.copy(P / "main.tex", P / "_old_sections" / "main_modular.tex") if (P / "_old_sections").mkdir(exist_ok=True) is None else None
    (P / "main.tex").write_text(main, encoding="utf-8")
    for f in (P / "sections").glob("*.tex"):
        shutil.move(str(f), str(P / "_old_sections" / f.name))
    (P / "sections").rmdir()
    print("main.tex flattened; modular sources moved to paper/_old_sections/")


def sync():
    main = (P / "main.tex").read_text(encoding="utf-8")
    n = 0
    for m in re.finditer(r"^% >>> ([a-z_]+) \(generated.*?\)\n.*?^% <<< \1$", main, flags=re.M | re.S):
        name = m.group(1)
        src = P / ("numbers.tex" if name == "numbers" else f"tables/{name}.tex")
        if not src.exists():
            continue
        new = block(name, src.read_text(encoding="utf-8"))
        if new != m.group(0):
            main = main.replace(m.group(0), new); n += 1
    (P / "main.tex").write_text(main, encoding="utf-8")
    print(f"main.tex: {n} generated block(s) updated")


if __name__ == "__main__":
    {"flatten": flatten, "sync": sync}[sys.argv[1]]()
